import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query' },
          limit: { type: 'integer', description: 'Max results (1-10)', minimum: 1, maximum: 10 }
        },
        required: ['query']
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error('Unknown tool: ' + name);
  }
  const { query, limit } = args || {};
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }
  if (limit !== undefined) {
    if (!Number.isInteger(limit) || limit < 1 || limit > 10) {
      throw new Error('limit must be an integer between 1 and 10');
    }
  }
  const q = query.toLowerCase();
  let results = products.filter(p => p.name.toLowerCase().includes(q));
  if (limit !== undefined) {
    results = results.slice(0, limit);
  }
  const text = results.length
    ? results.map(p => `${p.id}: ${p.name}`).join('\n')
    : 'No products found';
  return { content: [{ type: 'text', text }] };
}
